tags.gen_ai.tool.definitions:
[
  {
    "type": "function",
    "name": "get_comment_finds",
    "description": "Die neuen Kommentare je Issue seit dem letzten Anker: issueNumber, titel, coreItemId/coreText (das zugehoerige Core-Item; needsClarify=true heisst: es wartet auf eine Klaerungs-Antwort), comments (commentId, author, body).",
    "parameters": {
      "type": "object",
      "properties": {}
    }
  },
  {
    "type": "function",
    "name": "save_comment_drafts",
    "description": "Speichert die Destillate: je Fund MINDESTENS EIN Draft {issueNumber, commentIds (die tragenden Kommentare!), disposition (requirement|architecture|open_question|clarify_answer|noise), draftText (praezise deutsche Aussage; bei noise leer erlaubt), rationale, targetPbiId (NUR bei clarify_answer: das needs_clarify-PBI)}. Reines Geplauder = noise. Genau einmal aufrufen.",
    "parameters": {
      "type": "object",
      "properties": {
        "drafts": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "issueNumber": {
                "type": "integer"
              },
              "commentIds": {
                "type": "array",
                "items": {
                  "type": "integer"
                }
              },
              "disposition": {
                "type": "string"
              },
              "draftText": {
                "type": "string"
              },
              "rationale": {
                "type": "string"
              },
              "targetPbiId": {
                "type": [
                  "string",
                  "null"
                ],
                "default": null
              }
            },
            "required": [
              "issueNumber",
              "commentIds",
              "disposition",
              "draftText",
              "rationale"
            ]
          }
        }
      },
      "required": [
        "drafts"
      ]
    }
  }
]

tags.gen_ai.input.messages:
[
  {
    "role": "user",
    "parts": [
      {
        "type": "text",
        "content": "Destilliere die Issue-Diskussionen: get_comment_finds -> je Fund MINDESTENS EIN Draft mit disposition\n(requirement|architecture|open_question|clarify_answer|noise), den tragenden commentIds und praezisem\ndeutschen draftText (belegtreu, nichts erfinden; bei clarify_answer: targetPbiId = das needs_clarify-PBI).\nDu aenderst NIE das Issue und NIE die Wahrheit — du formulierst nur Vorschlaege.\nsave_comment_drafts GENAU EINMAL."
      }
    ]
  }
]

